document.addEventListener('DOMContentLoaded', async function() {
    // Trip data from server
    const tripData = ;
    const routePoints = ;

    console.log('Trip data:', tripData);
    console.log('Route points:', routePoints.length);

    // Initialize map
    const map = L.map('map').setView([tripData.current_lat, tripData.current_lng], 13);

    // Add tile layer
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors',
        maxZoom: 19
    }).addTo(map);

    // ✅ DRAW ROUTE USING OSRM (like vehicle tracking map)
    async function drawRoute(startLat, startLng, currentLat, currentLng, destLat, destLng) {
        try {
            // Create waypoints array: Start -> Current -> Dest
            const waypoints = [];
            if (startLat && startLng) {
                waypoints.push(`${startLng},${startLat}`);
            }
            if (currentLat && currentLng) {
                waypoints.push(`${currentLng},${currentLat}`);
            }
            if (destLat && destLng) {
                waypoints.push(`${destLng},${destLat}`);
            }

            // Need at least 2 points
            if (waypoints.length < 2) {
                console.log('Not enough points to draw route');
                return;
            }

            // Call OSRM API
            const osrmUrl = `https://router.project-osrm.org/route/v1/driving/${waypoints.join(';')}?overview=full&geometries=geojson`;

            const response = await fetch(osrmUrl);
            const data = await response.json();

            if (data.code === 'Ok' && data.routes && data.routes.length > 0) {
                const route = data.routes[0];
                const coordinates = route.geometry.coordinates;

                // Convert [lng, lat] to [lat, lng] for Leaflet
                const latLngs = coordinates.map(coord => [coord[1], coord[0]]);

                // Draw polyline
                const routeLine = L.polyline(latLngs, {
                    color: '#2563eb',
                    weight: 4,
                    opacity: 0.7,
                    lineJoin: 'round'
                }).addTo(map);

                // Add popup with route info
                const distance = (route.distance / 1000).toFixed(1); // km
                const duration = (route.duration / 60).toFixed(0); // minutes
                routeLine.bindPopup(
                    '<strong>Route Info</strong><br/>' +
                    'Distance: ' + distance + ' km<br/>' +
                    'Duration: ' + duration + ' minutes'
                );

                console.log(`✅ Route drawn: ${distance}km, ${duration}min`);
            } else {
                console.warn('⚠️ OSRM could not find route');
            }
        } catch (error) {
            console.error('❌ Error drawing route:', error);
        }
    }

    // Draw checkpoint dots (actual GPS history)
    if (routePoints.length > 0) {
        console.log(`Drawing ${routePoints.length} checkpoint dots`);

        routePoints.forEach(function(point, index) {
            // Show every 5th checkpoint (or first/last)
            if (index % 5 === 0 || index === 0 || index === routePoints.length - 1) {
                const marker = L.circleMarker([point.latitude, point.longitude], {
                    radius: 4,
                    fillColor: '#667eea',
                    color: '#fff',
                    weight: 1,
                    opacity: 1,
                    fillOpacity: 0.8
                }).addTo(map);

                marker.bindPopup('Checkpoint ' + (index + 1));
            }
        });
    }

    // Create vehicle icon
    const vehicleIcon = L.divIcon({
        html: '<div style="text-align: center;"><div style="font-size: 30px;">🚛</div><div style="background: white; padding: 4px 8px; border-radius: 4px; box-shadow: 0 2px 6px rgba(0,0,0,0.2); margin-top: 2px;"><div style="color: #2563eb; font-size: 10px; font-weight: bold;">' + tripData.driver_name.substring(0, 12) + '</div><div style="color: #dc2626; font-size: 9px;">' + tripData.vehicle_plate + '</div></div></div>',
        className: 'custom-vehicle-marker',
        iconSize: [45, 65],
        iconAnchor: [22, 32]
    });

    // Add vehicle marker
    const vehicleMarker = L.marker([tripData.current_lat, tripData.current_lng], {
        icon: vehicleIcon,
        zIndexOffset: 1000
    }).addTo(map);

    vehicleMarker.bindPopup('<h4>🚛 ' + tripData.vehicle_name + '</h4><div>Driver: ' + tripData.driver_name + '</div><div>Updated: ' + tripData.minutes_ago + ' min ago</div>');

    // Add start marker
    if (tripData.start_lat && tripData.start_lng) {
        const startIcon = L.divIcon({
            html: '🚩',
            className: 'custom-marker',
            iconSize: [25, 35],
            iconAnchor: [12, 35]
        });

        L.marker([tripData.start_lat, tripData.start_lng], {
            icon: startIcon
        }).addTo(map).bindPopup('🚩 Start: ' + tripData.start_name);
    }

    // Add destination marker
    if (tripData.dest_lat && tripData.dest_lng) {
        const destIcon = L.divIcon({
            html: '🎯',
            className: 'custom-marker',
            iconSize: [25, 35],
            iconAnchor: [12, 35]
        });

        L.marker([tripData.dest_lat, tripData.dest_lng], {
            icon: destIcon
        }).addTo(map).bindPopup('🎯 Destination: ' + tripData.dest_name);
    }

    // ✅ Draw OSRM route (after markers are added)
    await drawRoute(
        tripData.start_lat,
        tripData.start_lng,
        tripData.current_lat,
        tripData.current_lng,
        tripData.dest_lat,
        tripData.dest_lng
    );

    // Fit map bounds
    const bounds = [];

    if (routePoints.length > 0) {
        routePoints.forEach(function(point) {
            bounds.push([point.latitude, point.longitude]);
        });
    }

    bounds.push([tripData.current_lat, tripData.current_lng]);

    if (tripData.start_lat && tripData.start_lng) {
        bounds.push([tripData.start_lat, tripData.start_lng]);
    }
    if (tripData.dest_lat && tripData.dest_lng) {
        bounds.push([tripData.dest_lat, tripData.dest_lng]);
    }

    if (bounds.length > 1) {
        map.fitBounds(bounds, { padding: [80, 80] });
    }

    console.log('✅ Map initialized');
});
